import{_ as e,o as t,c as i,a2 as r}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Resistencia y recuperación","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/combat/stamina-and-reactive-combat.md","filePath":"es/guide/combat/stamina-and-reactive-combat.md"}'),o={name:"es/guide/combat/stamina-and-reactive-combat.md"};function c(n,a,s,d,l,p){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="stamina-and-reactive-combat" tabindex="-1">Resistencia y recuperación <a class="header-anchor" href="#stamina-and-reactive-combat" aria-label="Enlace permanente a &quot;Resistencia y recuperación&quot;">​</a></h1><p><strong>Estado:</strong> Propuesto: ampliación de recursos · Experimental: tiempos · Nuevos costes de acciones no implementados.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>La <a href="/Syrolands-Public/es/guide/glossary.html#stamina">resistencia</a> hace competir ataque, defensa y presión repetida.</li><li>Cada acción tiene preparación, contacto y <a href="/Syrolands-Public/es/guide/glossary.html#recovery">recuperación</a>; pulsar más no permite saltárselos.</li><li>Una DEX baja debe permitir un juego básico ágil; la fórmula final de Max Stamina sigue sin resolver.</li></ul><p><span id="at-a-glance"></span><span id="repeat-pressure"></span></p><h2 id="how-it-works" tabindex="-1">Cómo funciona <a class="header-anchor" href="#how-it-works" aria-label="Enlace permanente a &quot;Cómo funciona&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspecto</th><th>Significado</th></tr></thead><tbody><tr><td><a href="/Syrolands-Public/es/guide/glossary.html#wind-up">Preparación</a></td><td>Da al rival una oportunidad de reconocer la acción con la que te comprometes.</td></tr><tr><td><a href="/Syrolands-Public/es/guide/glossary.html#active-window">Fase activa</a></td><td>La acción puede conectar; no concede impactos gratuitos repetidos.</td></tr><tr><td>Recuperación</td><td>Termina el compromiso antes de la siguiente acción, incluida la defensa manual.</td></tr><tr><td>Precipitación</td><td>Comprometerte repetidamente demasiado pronto cuesta más resistencia, empeora la recuperación y puede reducir la precisión.</td></tr><tr><td>Orden rechazada</td><td>Un ataque no disponible no ocurre ni cobra su coste; pulsar repetidamente puede alterar <a href="/Syrolands-Public/es/guide/combat/flow.html">Flow</a>.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Comparado con UO clásico <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Enlace permanente a &quot;Comparado con UO clásico&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UO clásico</th><th>Syrolands</th></tr></thead><tbody><tr><td>La resistencia ya influye en la velocidad de golpeo</td><td>Hacer que las acciones físicas gasten resistencia explícitamente, con recuperación como compromiso separado.</td></tr><tr><td>Los especiales de armas del UO posterior usan maná</td><td>Explorar la resistencia como recurso principal de las acciones marciales.</td></tr></tbody></table><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Un ataque pesado falla. Aun así has gastado resistencia y debes terminar la recuperación, dando tiempo al rival para presionarte o cambiar la distancia.</p><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/combat/flow.html">Flow</a> · <a href="/Syrolands-Public/es/guide/characters/stats.html">Atributos</a></p><h2 id="full-design-specification" tabindex="-1">Especificación de diseño completa <a class="header-anchor" href="#full-design-specification" aria-label="Enlace permanente a &quot;Especificación de diseño completa&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/combat/stamina-and-reactive-combat.html">Leer la especificación de diseño completa</a></p><p><span id="timing-without-broken-early-characters"></span><span id="manual-attacks-are-a-proposal"></span></p>',16)])])}const h=e(o,[["render",c]]);export{u as __pageData,h as default};
